function isDigit(char) {
  return char >= '0' && char <= '9';
}

function looksLikeNegativeNumber(token) {
  if (token.length < 2 || token[0] !== '-') {
    return false;
  }

  if (isDigit(token[1])) {
    return true;
  }

  return token[1] === '.' && token.length > 2 && isDigit(token[2]);
}

function isOptionLike(token) {
  if (token.length === 0 || token[0] !== '-') {
    return false;
  }

  return !looksLikeNegativeNumber(token);
}

function basename(pathname) {
  let lastSlash = pathname.lastIndexOf('/');
  let lastBackslash = pathname.lastIndexOf('\\');

  if (lastBackslash > lastSlash) {
    lastSlash = lastBackslash;
  }

  return lastSlash === -1 ? pathname : pathname.slice(lastSlash + 1);
}

function usage(programName) {
  return `usage: ${programName} [-h] --a A\n`;
}

function help(programName) {
  return (
    `${usage(programName)}\n` +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n'
  );
}

function error(programName, message) {
  return `${usage(programName)}${programName}: error: ${message}\n`;
}

export function parseCommandLine(argv) {
  const programName = basename(argv[1] || 'test15.mjs');
  const tokens = argv.slice(2);
  const unknown = [];
  let value;

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
        code: 0,
        programName,
        stdout: help(programName),
      };
    }

    if (token === '--a') {
      const next = index + 1 < tokens.length ? tokens[index + 1] : undefined;

      if (next === undefined || isOptionLike(next)) {
        return {
          kind: 'error',
          code: 2,
          programName,
          stderr: error(programName, 'argument --a: expected one argument'),
        };
      }

      value = next;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      value = token.slice(4);
      continue;
    }

    unknown.push(token);
  }

  if (value === undefined) {
    return {
      kind: 'error',
      code: 2,
      programName,
      stderr: error(programName, 'the following arguments are required: --a'),
    };
  }

  if (unknown.length > 0) {
    return {
      kind: 'error',
      code: 2,
      programName,
      stderr: error(programName, `unrecognized arguments: ${unknown.join(' ')}`),
    };
  }

  return {
    kind: 'ok',
    code: 0,
    programName,
    value,
  };
